import java.util.*;

public class Main {
    int divide(int dividend, int divisor) {
        boolean negative = (dividend < 0) != (divisor < 0);  // result is negative if signs differ
        long dvd = Math.abs((long) dividend);
        long dvs = Math.abs((long) divisor);
        long quotient = 0;
        while (dvd >= dvs) {
            dvd -= dvs;                  // subtract one copy of the divisor at a time
            quotient += 1;                  // count each subtraction
        }
        return (int) (negative ? -quotient : quotient);
    }

    public static void main(String[] args) {
        int dividend = 10, divisor = 3;
        Main solution = new Main();
        System.out.println(solution.divide(dividend, divisor));
    }
}

